static id FZState(id logic) { if(!gMaps)gMaps=[NSMapTable weakToStrongObjectsMapTable]; NSMutableDictionary*s=[gMaps objectForKey:logic];if(!s){s=[@{ @"group":FZCurrentGroup(), @"rows":@[], @"names":@[], @"valid":@NO } mutableCopy];[gMaps setObject:s forKey:logic];}return s; }
static void FZSnapshot(id logic) { NSMutableDictionary*s=FZState(logic); NSString*group=s[@"group"]?:FZCurrentGroup(); NSMutableArray*rows=[NSMutableArray array];NSMutableArray*names=[NSMutableArray array];NSInteger count=0;@try{count=origCount?origCount(logic,@selector(getSessionCountForSection:),0):0;} @catch(__unused NSException*e){}if(count<0)count=0;for(NSInteger i=0;i<count;i++){NSIndexPath*p=[NSIndexPath indexPathForRow:i inSection:0];id session=nil;@try{session=origInfo(logic,@selector(getSessionInfoAtIndexPath:),p);} @catch(__unused NSException*e){}if(!session||FZMatches(session,group)){[rows addObject:@(i)];NSString*u=FZSessionUser(session);[names addObject:u?:@""];}}s[@"rows"]=rows;s[@"names"]=names;s[@"valid"]=@YES;}
static NSInteger FZMapRow(id logic,NSInteger row){NSDictionary*s=FZState(logic);if(![s[@"valid"]boolValue])FZSnapshot(logic);NSArray*r=s[@"rows"];return row>=0&&row<r.count?[r[row]integerValue]:NSIntegerMax;}
static id FZInfo(id self,SEL cmd,id path){NSInteger row=[path respondsToSelector:@selector(row)]?[path row]:0;NSInteger real=FZMapRow(self,row);if(real==NSIntegerMax)return nil;NSIndexPath*p=[NSIndexPath indexPathForRow:real inSection:[path section]];return origInfo(self,cmd,p);}
static id FZBase(id self,SEL cmd,id path){NSInteger row=[path respondsToSelector:@selector(row)]?[path row]:0;NSInteger real=FZMapRow(self,row);if(real==NSIntegerMax)return nil;NSIndexPath*p=[NSIndexPath indexPathForRow:real inSection:[path section]];return origBase(self,cmd,p);}
