static NSInteger FZCount(id self,SEL cmd,NSInteger section){FZSnapshot(self);return (NSInteger)[FZState(self)[@"rows"] count];}
static NSInteger FZReverse(id self,SEL cmd,id user,NSInteger section){FZSnapshot(self);NSArray*n=FZState(self)[@"names"];NSUInteger i=[n indexOfObject:user];if(i==NSNotFound)return NSIntegerMax;return (NSInteger)i;}
static void FZSessionReload(id self,SEL cmd){if(origReload)origReload(self,cmd);for(id logic in gMaps){NSMutableDictionary*s=[gMaps objectForKey:logic];s[@"valid"]=@NO;}FZRefreshAll();}
