static void FZPan(id self,SEL cmd,UIPanGestureRecognizer*g){if(g.state!=UIGestureRecognizerStateEnded)return;CGFloat x=[g translationInView:g.view].x;if(fabs(x)<40)return;NSArray*gs=FZVisibleGroups();if(gs.count<2)return;NSUInteger i=0;for(NSUInteger n=0;n<gs.count;n++)if([gs[n][@"name"]isEqual:FZCurrentGroup()]){i=n;break;}BOOL next=x<0;if(FZBool(@"WPPulse_ReverseSwipe",NO))next=!next;NSInteger j=next?(NSInteger)i+1:(NSInteger)i-1;if(j<0||j>=gs.count){if(!FZBool(@"WPPulse_LoopSwipe",YES))return;j=(j+gs.count)%gs.count;}FZSelectGroup(gs[j][@"name"]);if(FZInteger(@"WPPulse_HapticLevel",1)>0){UIImpactFeedbackGenerator*h=[[UIImpactFeedbackGenerator alloc]initWithStyle:UIImpactFeedbackStyleLight];[h impactOccurred];}}
static void FZLong(id self,SEL cmd,UILongPressGestureRecognizer*g){if(g.state==UIGestureRecognizerStateBegan){UIViewController*c=(UIViewController*)self;WPCustomSettingsPanel*p=[WPCustomSettingsPanel new];[c.navigationController pushViewController:p animated:YES];}}
static void FZAddUIMethods(Class cls){class_addMethod(cls,sel_registerName("fz_handlePan:"),(IMP)FZPan,"v24@0:8@");class_addMethod(cls,sel_registerName("fz_handleLongPress:"),(IMP)FZLong,"v24@0:8@");}
void FZRefreshAll(void){dispatch_async(dispatch_get_main_queue(),^{UIViewController*c=FZTopViewController();FZRefreshUI(c);if([c respondsToSelector:@selector(view)]) [c.view setNeedsLayout];});}
static void FZHook(Class cls,SEL sel,IMP imp,IMP*orig){if(cls&&class_getInstanceMethod(cls,sel))MSHookMessageEx(cls,sel,imp,orig);}
void FZInstallHooks(void){if(gInstalled)return;gInstalled=YES;gMaps=[NSMapTable weakToStrongObjectsMapTable];[[NSNotificationCenter defaultCenter]addObserverForName:FZGroupChanged object:nil queue:NSOperationQueue.mainQueue usingBlock:FZSelectChanged];[[NSNotificationCenter defaultCenter]addObserverForName:FZConfigChanged object:nil queue:NSOperationQueue.mainQueue usingBlock:FZSelectChanged];Class logic=objc_getClass("MainFrameLogicController");FZHook(logic,@selector(getSessionCountForSection:),(IMP)FZCount,(IMP*)&origCount);FZHook(logic,@selector(getSessionInfoAtIndexPath:),(IMP)FZInfo,(IMP*)&origInfo);FZHook(logic,@selector(getSessionBaseInfoAtIndexPath:),(IMP)FZBase,(IMP*)&origBase);FZHook(logic,@selector(getCellDataAtIndexPath:),(IMP)FZCell,(IMP*)&origCell);FZHook(logic,@selector(indexOfSessionUserName:inSection:),(IMP)FZReverse,(IMP*)&origReverse);NSArray*classes=@[@"MainSessionMgr",@"MMNewSessionMgr",@"SessionMgr"];for(NSString*n in classes){Class c=objc_getClass(n);FZHook(c,@selector(reloadSessions),(IMP)FZSessionReload,(IMP*)&origReload);FZHook(c,@selector(visibleTopSessionCount),(IMP)FZCount,(IMP*)&origTopCount);FZHook(c,@selector(visibleNormalSessionCount),(IMP)FZCount,(IMP*)&origNormalCount);FZHook(c,@selector(getTopSessionAtIndex:),(IMP)FZInfo,(IMP*)&origTopAt);FZHook(c,@selector(getNormalSessionAtIndex:),(IMP)FZInfo,(IMP*)&origNormalAt);FZHook(c,@selector(GetSessionCount),(IMP)FZCount,(IMP*)&origGetCount);FZHook(c,@selector(GetSessionAtIndex:),(IMP)FZInfo,(IMP*)&origGetAt);}Class home=objc_getClass("NewMainFrameViewController");FZAddUIMethods(home);FZHook(home,@selector(viewDidAppear:),(IMP)FZAppear,(IMP*)&origAppear);FZHook(home,@selector(viewDidLoad),(IMP)FZLoad,(IMP*)&origLoad);FZHook(home,@selector(viewDidLayoutSubviews),(IMP)FZLayout,(IMP*)&origLayout);Class settings=objc_getClass("NewSettingViewController");FZHook(settings,@selector(viewDidAppear:),(IMP)FZAppear,(IMP*)&origAppear);}
__attribute__((constructor))static void FZInit(void){@autoreleasepool{if(![NSBundle.mainBundle.bundleIdentifier isEqual:@"com.tencent.xin"])return;dispatch_async(dispatch_get_main_queue(),^{FZInstallHooks();});}}
